(function(){'use strict';
const KEY='nawaf-hq-v5',THEME='nawaf-hq-theme-v19';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const icons={dashboard:'⌂',workforce:'◎',projects:'▱',tasks:'✓',reports:'▤'};
function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{return {}}}
function ago(v){const t=Date.parse(v||'');if(!Number.isFinite(t))return '';const m=Math.max(1,Math.floor((Date.now()-t)/60000));return m<60?`منذ ${m} د`:m<1440?`منذ ${Math.floor(m/60)} س`:`منذ ${Math.floor(m/1440)} ي`}
function applyTheme(name){document.documentElement.dataset.hqTheme=name;localStorage.setItem(THEME,name);document.querySelectorAll('[data-theme-v19]').forEach(b=>b.classList.toggle('active',b.dataset.themeV19===name))}
function enhanceNav(){const brand=$('.v8-brand');if(brand&&!brand.querySelector('.v19-mark'))brand.innerHTML='<span class="v19-mark">N</span><span><b>NAWAF HQ</b><small>COMPANY OS · V2</small></span>';document.querySelectorAll('.v8-side [data-view]').forEach(b=>{const id=b.dataset.view;if(!b.querySelector('i'))b.insertAdjacentHTML('afterbegin',`<i>${icons[id]||'·'}</i>`)})}
function hero(){const h=$('.v14-hero');if(!h||h.dataset.v19)return;h.dataset.v19='1';h.innerHTML=`<div class="v19-hero-copy"><span class="v14-eyebrow">NAWAF HQ · AI COMPANY OPERATING SYSTEM</span><h2>صباح الخير <em>نواف</em></h2><p>فريقك جاهز. حوّل الفكرة إلى تنفيذ من مكان واحد.</p><div class="v19-command" role="button" tabindex="0" data-v19-command><span>✦</span><b>وش تبغى الشركة تسوي؟</b><small>اكتب أمرًا أو ابدأ مهمة جديدة</small><i>تنفيذ الآن ←</i></div><div class="v19-pills"><button data-v19-command>حل مشكلة تقنية</button><button data-v19-command>حلّل أداء مشروع</button><button data-v19-command>جهّز تقريرًا</button></div></div><div class="v19-hero-meta"><span>جاهزية التشغيل</span><strong>${$('.v14-score strong')?.textContent||'—'}</strong><small>بيانات فعلية من مهامك</small></div>`;h.querySelectorAll('[data-v19-command]').forEach(b=>b.onclick=()=>document.querySelector('[data-v9-quick]')?.click())}
function themes(){const header=$('.v8-header');if(!header||header.querySelector('.v19-themes'))return;const wrap=document.createElement('div');wrap.className='v19-themes';wrap.setAttribute('aria-label','اختيار المظهر');wrap.innerHTML='<button data-theme-v19="mountain" title="الجبل السينمائي">☀</button><button data-theme-v19="aurora" title="الشفق التنفيذي">✦</button><button data-theme-v19="command" title="مركز القيادة">⌁</button>';header.querySelector('.v8-actions')?.prepend(wrap);wrap.onclick=e=>{const b=e.target.closest('[data-theme-v19]');if(b)applyTheme(b.dataset.themeV19)};applyTheme(localStorage.getItem(THEME)||'mountain')}
function rail(){const app=$('.v8');if(!app)return;let r=$('.v19-rail');if(!r){r=document.createElement('aside');r.className='v19-rail';app.appendChild(r)}const s=read(),tasks=s.tasks||[],waiting=tasks.filter(t=>t.status==='WAITING_FOR_NAWAF'),blocked=tasks.filter(t=>t.blockedReason&&t.status!=='COMPLETED'),activity=(s.activity||[]).slice(0,4),active=tasks.filter(t=>['WORKING','RESEARCHING','REVIEWING'].includes(t.status));r.innerHTML=`<div class="v19-profile"><span>ن</span><div><b>نواف</b><small>الرئيس التنفيذي</small></div><i></i></div><section><header><span>الموجز التنفيذي</span><b>${waiting.length+blocked.length}</b></header><h3>${waiting.length||blocked.length?'توجد عناصر تحتاج انتباهك':'الوضع مستقر وجاهز للتنفيذ'}</h3><p>${active.length} مهام تعمل الآن، ${waiting.length} قرارات بانتظارك، و${blocked.length} عوائق مسجلة.</p><button data-v19-decisions>عرض مركز القرارات ←</button></section><section><header><span>صحة النظام</span><i class="ok">مستقر</i></header><div class="v19-health"><strong>${blocked.length?'92':'99'}%</strong><span>المحرك والمزامنة يعملان</span></div><ul><li>محرك التنفيذ <i></i></li><li>الحالة السحابية <i></i></li><li>واجهة القيادة <i></i></li></ul></section><section><header><span>آخر النشاط</span></header><div class="v19-activity">${activity.length?activity.map(a=>`<p><i></i><span>${esc(a.text||'نشاط')}</span><small>${ago(a.at)}</small></p>`).join(''):'<p class="empty">لا يوجد نشاط مسجل بعد.</p>'}</div></section>`;r.querySelector('[data-v19-decisions]')?.addEventListener('click',()=>window.NawafHQV13?.openCenter?.())}
function enhance(){enhanceNav();themes();hero();rail();document.querySelectorAll('.v8-project').forEach((p,i)=>p.dataset.visual=['mueen','qaddha','nav'][i%3])}
let t;function schedule(){clearTimeout(t);t=setTimeout(enhance,80)}function boot(){applyTheme(localStorage.getItem(THEME)||'mountain');new MutationObserver(schedule).observe(document.body,{childList:true,subtree:true});window.addEventListener('nawaf:state-updated',schedule);enhance()}document.readyState==='loading'?document.addEventListener('DOMContentLoaded',boot):boot();
})();
